'use client';
import { OrbitControls, SoftShadows } from '@react-three/drei';
import { useThree } from '@react-three/fiber';
import { folder, useControls } from 'leva';
import { FC, Suspense, useEffect, useMemo, useRef } from 'react';
import * as THREE from 'three';
import type { OrbitControls as OrbitControlsImpl } from 'three-stdlib';
import { clampDoorHeightMm, lights } from '../const';
import { useDoorHeight, useIsFrontSide, useSceneLightingMode } from '../store';
import { Connectors } from './Connectors';
import { Cylinder } from './Cylinder';
import { DoorApplication } from './DoorApplication';
import { InnerHandle } from './InnerHandle';
import { OuterHandle } from './OuterHandle';
import { HardwareGroup, ParametricDoor, ParametricHouse } from './parametric';
import {
  WALL_CENTER_Z,
  WALL_HEIGHT,
  WALL_THICKNESS,
} from './parametric/ParametricWall';

interface Props {
  proposal?: Proposal;
  onLoadingChange?: (loading: boolean) => void;
}

const SuspenseNotifier: FC<{
  onLoadingChange?: (loading: boolean) => void;
}> = ({ onLoadingChange }) => {
  useEffect(() => {
    onLoadingChange?.(false);
    return () => {
      onLoadingChange?.(true);
    };
  }, [onLoadingChange]);
  return null;
};

const interiorLampPosition: [number, number, number] = [0, 1.72, -5.15];
const wallLightPositions: [number, number, number][] = [
  [-1.08, 1.58, 0.11],
  [1.08, 1.58, 0.11],
];

interface DoorCameraControllerProps {
  controlsRef: React.RefObject<OrbitControlsImpl | null>;
  doorFocusY: number;
  isFront: boolean;
}

const DoorCameraController: FC<DoorCameraControllerProps> = ({
  controlsRef,
  doorFocusY,
  isFront,
}) => {
  const { camera, invalidate } = useThree();

  useEffect(() => {
    const controls = controlsRef.current;

    if (!controls) return;

    const interiorTargetZ = WALL_CENTER_Z - WALL_THICKNESS / 2 - 0.02;
    const target = new THREE.Vector3(
      0,
      doorFocusY,
      isFront ? 0 : interiorTargetZ,
    );
    const offset = isFront
      ? new THREE.Vector3(0, 0.8, 4.5)
      : new THREE.Vector3(0, 0.8, -4.5);

    controls.target.copy(target);
    camera.position.copy(target).add(offset);
    camera.lookAt(target);
    controls.update();
    invalidate();
  }, [camera, controlsRef, doorFocusY, invalidate, isFront]);

  return null;
};

const ExposureController: FC<{ exposure: number }> = ({ exposure }) => {
  const { gl, invalidate } = useThree();
  useEffect(() => {
    gl.toneMappingExposure = exposure;
    invalidate();
  }, [gl, exposure, invalidate]);
  return null;
};

const InteriorNightLamp: FC<{
  isNightMode: boolean;
  pointIntensity?: number;
  spotIntensity?: number;
}> = ({ isNightMode, pointIntensity = 11, spotIntensity = 13 }) => {
  const target = useMemo(() => {
    const nextTarget = new THREE.Object3D();
    nextTarget.position.set(0, -1.9, 0);
    return nextTarget;
  }, []);

  return (
    <group position={interiorLampPosition}>
      <primitive object={target} />
      <mesh position={[0, 0.11, 0]}>
        <cylinderGeometry args={[0.045, 0.045, 0.22, 24]} />
        <meshStandardMaterial
          color="#2c3137"
          roughness={0.72}
          metalness={0.18}
        />
      </mesh>
      <mesh castShadow position={[0, -0.03, 0]}>
        <cylinderGeometry args={[0.22, 0.28, 0.18, 32]} />
        <meshStandardMaterial
          color="#d8c7a2"
          metalness={0.08}
          roughness={0.55}
        />
      </mesh>
      <mesh position={[0, -0.09, 0]}>
        <sphereGeometry args={[0.11, 24, 24]} />
        <meshStandardMaterial
          color="#ffe5b7"
          emissive="#ffcc7a"
          emissiveIntensity={isNightMode ? 2.9 : 0.12}
          roughness={0.2}
        />
      </mesh>
      <pointLight
        position={[0, -0.16, 0]}
        intensity={isNightMode ? pointIntensity : 0}
        distance={9}
        decay={1.4}
        color="#ffd8a6"
      />
      <spotLight
        position={[0, -0.07, 0]}
        target={target}
        angle={1.05}
        penumbra={1}
        decay={1.15}
        distance={11}
        intensity={isNightMode ? spotIntensity : 0}
        color="#ffd8a6"
        castShadow
        shadow-bias={-0.0001}
        shadow-radius={5}
        shadow-mapSize-width={2048}
        shadow-mapSize-height={2048}
      />
    </group>
  );
};

const WallMountedLights: FC<{
  isNightMode: boolean;
  isVisible: boolean;
  nightIntensity?: number;
}> = ({ isNightMode, isVisible, nightIntensity = 18 }) => {
  const targets = useMemo(
    () =>
      wallLightPositions.map((_, index) => {
        const target = new THREE.Object3D();
        target.position.set(index === 0 ? 0.92 : -0.92, -1.15, -1.05);
        return target;
      }),
    [],
  );

  return (
    <group>
      {wallLightPositions.map((position, index) => (
        <group key={`wall-light-${index}`} position={position}>
          <primitive object={targets[index]} />
          <mesh castShadow position={[0, 0, -0.025]}>
            <boxGeometry args={[0.16, 0.22, 0.05]} />
            <meshStandardMaterial
              color="#2c3137"
              roughness={0.82}
              metalness={0.18}
            />
          </mesh>
          <mesh position={[0, -0.02, 0.005]}>
            <boxGeometry args={[0.09, 0.11, 0.03]} />
            <meshStandardMaterial
              color="#ffe1b3"
              emissive="#ffc76d"
              emissiveIntensity={isNightMode ? 2.3 : 0.06}
              roughness={0.3}
            />
          </mesh>
          <spotLight
            position={[0, -0.02, 0.03]}
            target={targets[index]}
            angle={1.08}
            penumbra={1}
            decay={1}
            distance={13}
            intensity={isNightMode && isVisible ? nightIntensity : 0}
            color="#ffe0b0"
            castShadow
            shadow-bias={-0.0001}
            shadow-radius={3}
            shadow-mapSize-width={2048}
            shadow-mapSize-height={2048}
          />
        </group>
      ))}
    </group>
  );
};

export const Door: FC<Props> = ({ proposal, onLoadingChange }) => {
  const isFront = useIsFrontSide();
  const selectedDoorHeightMm = useDoorHeight();
  const selectedLightingMode = useSceneLightingMode();
  const controlsRef = useRef<OrbitControlsImpl | null>(null);
  const isNightMode = selectedLightingMode?.id === 'night';
  const minDistance = isFront ? 3 : 3.2;
  const maxDistance = isFront ? 8 : 6.5;
  const minPolarAngle = isFront ? Math.PI / 3 : 1.22;
  const maxPolarAngle = isFront ? Math.PI / 2 : 1.5;
  const maxAzimuthAngle = useMemo(
    () => (isFront ? Math.PI / 6 : Math.PI + Math.PI / 6),
    [isFront],
  );
  const minAzimuthAngle = useMemo(() => {
    return isFront ? -Math.PI / 6 : Math.PI - Math.PI / 6;
  }, [isFront]);
  const doorFocusY = useMemo(() => {
    const doorHeight =
      clampDoorHeightMm(proposal?.doorHeight ?? selectedDoorHeightMm) / 1000;

    return -WALL_HEIGHT / 2 + 0.03 + doorHeight / 2;
  }, [proposal?.doorHeight, selectedDoorHeightMm]);

  const {
    exposure,
    dayKeyX,
    dayKeyY,
    dayKeyZ,
    dayKeyIntensity,
    dayDetailX,
    dayDetailY,
    dayDetailZ,
    dayDetailIntensity,
    dayAmbIntensity,
    dayHemiIntensity,
    nightDirIntensity,
    nightAmbIntensity,
    nightHemiIntensity,
    nightWallLampIntensity,
    nightPointLampIntensity,
    nightSpotLampIntensity,
  } = useControls({
    'Post FX': folder({
      exposure: { value: 1.0, min: 0.1, max: 3, step: 0.05, label: 'Exposure' },
    }),
    'Day Lights': folder(
      {
        'Key Light (raking)': folder({
          dayKeyX: { value: -8, min: -8, max: 10, step: 0.1, label: 'X' },
          dayKeyY: { value: 10, min: 0, max: 10, step: 0.1, label: 'Y' },
          dayKeyZ: { value: 1.5, min: -2, max: 12, step: 0.1, label: 'Z' },
          dayKeyIntensity: {
            value: 6,
            min: 0,
            max: 6,
            step: 0.05,
            label: 'Intensity',
          },
        }),
        'Detail Fill (opposite side)': folder({
          dayDetailX: { value: 4.6, min: -8, max: 8, step: 0.1, label: 'X' },
          dayDetailY: { value: 3.0, min: 0, max: 8, step: 0.1, label: 'Y' },
          dayDetailZ: { value: -5.3, min: -8, max: 10, step: 0.1, label: 'Z' },
          dayDetailIntensity: {
            value: 0.7,
            min: 0,
            max: 3,
            step: 0.05,
            label: 'Intensity',
          },
        }),
        dayAmbIntensity: {
          value: 0.2,
          min: 0,
          max: 3,
          step: 0.05,
          label: 'Ambient',
        },
        dayHemiIntensity: {
          value: 0.25,
          min: 0,
          max: 3,
          step: 0.05,
          label: 'Hemisphere',
        },
      },
      { collapsed: false },
    ),
    'Night Lights': folder(
      {
        nightDirIntensity: {
          value: 5,
          min: 0,
          max: 5,
          step: 0.05,
          label: 'Directional',
        },
        nightAmbIntensity: {
          value: 0.24,
          min: 0,
          max: 2,
          step: 0.05,
          label: 'Ambient',
        },
        nightHemiIntensity: {
          value: 0,
          min: 0,
          max: 2,
          step: 0.05,
          label: 'Hemisphere',
        },
        nightWallLampIntensity: {
          value: 9,
          min: 0,
          max: 60,
          step: 0.5,
          label: 'Wall Lamps',
        },
        nightPointLampIntensity: {
          value: 11,
          min: 0,
          max: 30,
          step: 0.5,
          label: 'Interior Pt',
        },
        nightSpotLampIntensity: {
          value: 13,
          min: 0,
          max: 40,
          step: 0.5,
          label: 'Interior Sp',
        },
      },
      { collapsed: true },
    ),
  });

  return (
    <group position={[0, 0, 0]}>
      <ExposureController exposure={exposure} />
      <DoorCameraController
        controlsRef={controlsRef}
        doorFocusY={doorFocusY}
        isFront={isFront}
      />
      <OrbitControls
        ref={controlsRef}
        minDistance={minDistance}
        maxDistance={maxDistance}
        maxPolarAngle={maxPolarAngle}
        minPolarAngle={minPolarAngle}
        maxAzimuthAngle={maxAzimuthAngle}
        minAzimuthAngle={minAzimuthAngle}
        target={[0, doorFocusY, 0]}
        enablePan={false}
      />
      <SoftShadows size={25} samples={17} focus={0} />
      <color attach="background" args={[isNightMode ? '#0d1320' : '#edf1f4']} />
      <fog
        attach="fog"
        args={[
          isNightMode ? '#0d1320' : '#edf1f4',
          isNightMode ? 8 : 180,
          isNightMode ? 24 : 240,
        ]}
      />
      {isFront ? (
        <>
          {/* Key light — raking from the side to reveal engraved details */}
          <directionalLight
            {...lights.front}
            position={[dayKeyX, dayKeyY, dayKeyZ] as [number, number, number]}
            castShadow
            intensity={isNightMode ? nightDirIntensity : dayKeyIntensity}
            color={isNightMode ? '#a9bce0' : '#ffffff'}
            shadow-bias={-0.0001}
            shadow-radius={3}
            shadow-mapSize-width={4096}
            shadow-mapSize-height={4096}
            shadow-camera-left={-3}
            shadow-camera-right={3}
            shadow-camera-top={4}
            shadow-camera-bottom={-2}
            shadow-camera-near={0.5}
            shadow-camera-far={25}
          />
          {/* Detail fill — from the opposite side, softer, prevents full black shadows */}
          {!isNightMode && (
            <directionalLight
              position={
                [dayDetailX, dayDetailY, dayDetailZ] as [number, number, number]
              }
              intensity={dayDetailIntensity}
              color="#e8eeff"
            />
          )}
          <ambientLight
            intensity={isNightMode ? nightAmbIntensity : dayAmbIntensity}
            color={isNightMode ? '#8d9ab0' : '#ffffff'}
          />
          <hemisphereLight
            color={isNightMode ? '#94a7c6' : '#ffffff'}
            groundColor={isNightMode ? '#1b2028' : '#888888'}
            intensity={isNightMode ? nightHemiIntensity : dayHemiIntensity}
          />
          <directionalLight
            position={[2, 2, -3]}
            intensity={isNightMode ? 0.22 : 0.35}
            color={isNightMode ? '#b0c1dd' : '#ffffff'}
          />
          <pointLight
            position={[-2, 2, -2]}
            intensity={isNightMode ? 0 : 0.3}
            distance={7}
          />
          <pointLight
            position={[2, 2, -2]}
            intensity={isNightMode ? 0 : 0.3}
            distance={7}
          />
        </>
      ) : (
        <>
          <ambientLight
            intensity={isNightMode ? nightAmbIntensity * 0.75 : 0.35}
            color={isNightMode ? '#7d8ca3' : '#ffffff'}
          />
          <hemisphereLight
            color={isNightMode ? '#7183a0' : '#ffffff'}
            groundColor={isNightMode ? '#16181f' : '#888888'}
            intensity={isNightMode ? nightHemiIntensity * 0.52 : 0.2}
          />
        </>
      )}
      <WallMountedLights
        isNightMode={isNightMode}
        isVisible={isFront}
        nightIntensity={nightWallLampIntensity}
      />
      <InteriorNightLamp
        isNightMode={isNightMode || !isFront}
        pointIntensity={nightPointLampIntensity}
        spotIntensity={nightSpotLampIntensity}
      />

      {/* House structure with the first-floor slab/ceiling restored */}
      <ParametricHouse proposal={proposal} />

      {/* Door model + hardware — wrapped in Suspense so the scene stays
          rendered while new GLTFs load (only the models unmount, not the
          lights/camera/walls). */}
      <Suspense fallback={null}>
        <SuspenseNotifier onLoadingChange={onLoadingChange} />
        <ParametricDoor showWall={false} />
        <HardwareGroup>
          <DoorApplication proposal={proposal} />
          <Cylinder proposal={proposal} />
          <Connectors proposal={proposal} />
          <OuterHandle proposal={proposal} />
          <InnerHandle proposal={proposal} />
        </HardwareGroup>
      </Suspense>
    </group>
  );
};

/*
Auto-generated by: https://github.com/pmndrs/gltfjsx
Command: npx gltfjsx@6.2.16 3-dimensions.glb --types
*/

import {
  WALL_CENTER_Z,
  WALL_THICKNESS,
} from '@modules/door-model/components/parametric/ParametricWall';
import { useDoorMaterial } from '@modules/door-model/hooks/useDoorMaterials';
import { useGLTF } from '@react-three/drei';
import { FC, useEffect, useMemo } from 'react';
import * as THREE from 'three';
import { GLTF } from 'three-stdlib';

type GLTFResult = GLTF & {
  nodes: Record<string, THREE.Mesh>;
  materials: {
    Boja1: THREE.MeshStandardMaterial;
  };
};

// ── Size definitions ──────────────────────────────────────────────────────────
export type DoorPanelSize = 'L' | 'M' | 'S';

/** Returns the V (front) and U (back) node keys for a given design and size. */
function meshKeys(designId: string, size: DoorPanelSize): [string, string] {
  const id = designId.toUpperCase();
  return [`${id}-${size}-V-P1`, `${id}-${size}-U-P1`];
}

/** Returns the V-int (front) and U-int (back) interior node keys for a given design and size. */
function intMeshKeys(designId: string, size: DoorPanelSize): [string, string] {
  const id = designId.toUpperCase();
  return [`${id}-${size}-V-int`, `${id}-${size}-U-int`];
}

/** Returns the V-staklo (front) and U-staklo (back) glass node keys for a given design and size. */
function stakloMeshKeys(
  designId: string,
  size: DoorPanelSize,
): [string, string] {
  const id = designId.toUpperCase();
  return [`${id}-${size}-V-staklo`, `${id}-${size}-U-staklo`];
}

/**
 * Fallback: scans all nodes for a staklo mesh matching the given size and side.
 * Handles GLBs where staklo nodes were exported with a different design ID prefix.
 */
function findStakloNode(
  nodes: Record<string, THREE.Mesh>,
  size: DoorPanelSize,
  side: 'V' | 'U',
): THREE.Mesh | null {
  const suffix = `-${size}-${side}-staklo`;
  const entry = Object.entries(nodes).find(([key]) => key.endsWith(suffix));
  return entry ? (entry[1] as THREE.Mesh) : null;
}

// ── Bounding-box helpers ──────────────────────────────────────────────────────
export interface DoorPanelBounds {
  /** Panel width in meters (X extent) */
  width: number;
  /** Panel height in meters (Y extent) */
  height: number;
  /** Panel depth/thickness in meters (Z extent) */
  depth: number;
}

/** Compute bounding box for a single mesh. */
function computeSingleMeshBounds(mesh: THREE.Mesh) {
  const box = new THREE.Box3();
  if (mesh?.geometry) {
    mesh.geometry.computeBoundingBox();
    if (mesh.geometry.boundingBox) {
      box.copy(mesh.geometry.boundingBox);
    }
  }
  const sizeVec = new THREE.Vector3();
  const center = new THREE.Vector3();
  box.getSize(sizeVec);
  box.getCenter(center);
  return { box, sizeVec, center };
}

/** Compute combined bounding box for both meshes of a size variant. */
function computeBoundsForSize(
  nodes: GLTFResult['nodes'],
  size: DoorPanelSize,
  designId: string,
) {
  const box = new THREE.Box3();
  const [key1, key2] = meshKeys(designId, size);

  [nodes[key1], nodes[key2]].forEach((mesh) => {
    if (mesh?.geometry) {
      mesh.geometry.computeBoundingBox();
      if (mesh.geometry.boundingBox) {
        box.union(mesh.geometry.boundingBox);
      }
    }
  });

  const sizeVec = new THREE.Vector3();
  const center = new THREE.Vector3();
  box.getSize(sizeVec);
  box.getCenter(center);

  return { sizeVec, center };
}

/**
 * Compute the scale factors needed to make the -V (front) mesh
 * match the -U (back) mesh dimensions.
 * The -V meshes are ~50mm smaller in width and height across all sizes.
 */
function computeVScaleFactors(
  nodes: GLTFResult['nodes'],
  size: DoorPanelSize,
  designId: string,
) {
  const [vKey, uKey] = meshKeys(designId, size);
  const vBounds = computeSingleMeshBounds(nodes[vKey]);
  const uBounds = computeSingleMeshBounds(nodes[uKey]);

  return {
    scaleX: vBounds.sizeVec.x > 0 ? uBounds.sizeVec.x / vBounds.sizeVec.x : 1,
    scaleY: vBounds.sizeVec.y > 0 ? uBounds.sizeVec.y / vBounds.sizeVec.y : 1,
    // Keep Z (depth) at 1 — both panels are the same thickness
    vCenter: vBounds.center,
    uCenter: uBounds.center,
  };
}

/**
 * Returns the bounding-box dimensions (in meters) of the door panel model
 * for the given size variant.
 *
 * The model is already in meters (exported via Blender glTF I/O).
 * Cached via useGLTF internally — safe to call from multiple components.
 */
export function useDoorPanelBounds(
  modelSrc: string,
  designId: string,
  size: DoorPanelSize = 'L',
): DoorPanelBounds {
  const { nodes } = useGLTF(modelSrc) as unknown as GLTFResult;

  return useMemo(() => {
    const { sizeVec } = computeBoundsForSize(nodes, size, designId);
    return {
      width: sizeVec.x,
      height: sizeVec.y,
      depth: sizeVec.z,
    };
  }, [nodes, size, designId]);
}

// ── Component ─────────────────────────────────────────────────────────────────
interface DoorPanelProps {
  modelSrc: string;
  designId: string;
  size?: DoorPanelSize;
  targetWidth?: number;
  targetHeight?: number;
  materialId?: string;
  position?: [number, number, number];
  mirrored?: boolean;
}

/**
 * Renders the door panel 3D model for the selected design and size.
 * The model is auto-centered at the group's origin so frame / glass / wall
 * can be positioned relative to its geometric center.
 */
export const DoorPanel: FC<DoorPanelProps> = ({
  modelSrc,
  designId,
  size = 'L',
  targetWidth,
  targetHeight,
  materialId,
  position = [0, 0, 0],
  mirrored = false,
}) => {
  const { nodes, materials } = useGLTF(modelSrc) as unknown as GLTFResult;
  const ralMaterial = useDoorMaterial(materialId);
  const [panelX, panelY] = position;

  const panelBounds = useMemo(() => {
    return computeBoundsForSize(nodes, size, designId);
  }, [nodes, size, designId]);

  const centerOffset = panelBounds.center;
  const sourceWidth = panelBounds.sizeVec.x || 1;
  const sourceHeight = panelBounds.sizeVec.y || 1;
  const resolvedWidth = targetWidth ?? sourceWidth;
  const resolvedHeight = targetHeight ?? sourceHeight;

  // Scale the selected source model to requested target dimensions.
  const targetScaleX = resolvedWidth / sourceWidth;
  const targetScaleY = resolvedHeight / sourceHeight;

  // Scale the -V (front) mesh to match the -U (back) mesh dimensions first.
  const vScale = useMemo(() => {
    const { scaleX, scaleY, vCenter, uCenter } = computeVScaleFactors(
      nodes,
      size,
      designId,
    );
    return { scaleX, scaleY, vCenter, uCenter };
  }, [nodes, size, designId]);

  const [vKey, uKey] = meshKeys(designId, size);
  const [vIntKey, uIntKey] = intMeshKeys(designId, size);
  const vIntMesh = nodes[vIntKey] ?? null;
  const uIntMesh = nodes[uIntKey] ?? null;

  const [vStakloKey, uStakloKey] = stakloMeshKeys(designId, size);
  const vStakloMesh = nodes[vStakloKey] ?? findStakloNode(nodes, size, 'V');
  const uStakloMesh = nodes[uStakloKey] ?? findStakloNode(nodes, size, 'U');
  const halfTargetWidth = resolvedWidth / 2;
  const halfTargetHeight = resolvedHeight / 2;

  const clippingPlanes = useMemo(() => {
    // Keep panel clipped to requested width/height around its own center.
    const left = panelX - halfTargetWidth;
    const right = panelX + halfTargetWidth;
    const bottom = panelY - halfTargetHeight;
    const top = panelY + halfTargetHeight;

    const wallHalfDepth = WALL_THICKNESS / 2;
    const wallFrontZ = WALL_CENTER_Z + wallHalfDepth;
    const wallBackZ = WALL_CENTER_Z - wallHalfDepth;

    return [
      new THREE.Plane(new THREE.Vector3(1, 0, 0), -left),
      new THREE.Plane(new THREE.Vector3(-1, 0, 0), right),
      new THREE.Plane(new THREE.Vector3(0, 1, 0), -bottom),
      new THREE.Plane(new THREE.Vector3(0, -1, 0), top),
      new THREE.Plane(new THREE.Vector3(0, 0, 1), -wallBackZ),
      new THREE.Plane(new THREE.Vector3(0, 0, -1), wallFrontZ),
    ];
  }, [halfTargetHeight, halfTargetWidth, panelX, panelY]);

  const clippedMaterial = useMemo(() => {
    const base = ralMaterial ?? materials.Boja1;
    const material = base.clone();
    material.clippingPlanes = clippingPlanes;
    material.clipShadows = true;
    material.needsUpdate = true;
    return material;
  }, [clippingPlanes, ralMaterial, materials.Boja1]);

  useEffect(() => {
    return () => {
      clippedMaterial.dispose();
    };
  }, [clippedMaterial]);

  const clippedIntMaterial = useMemo(() => {
    const intNode = vIntMesh ?? uIntMesh;
    if (!intNode) return null;
    const base = Array.isArray(intNode.material)
      ? intNode.material[0]
      : intNode.material;
    const material = (base as THREE.MeshStandardMaterial).clone();
    material.clippingPlanes = clippingPlanes;
    material.clipShadows = true;
    material.needsUpdate = true;
    return material;
  }, [clippingPlanes, vIntMesh, uIntMesh]);

  useEffect(() => {
    return () => {
      clippedIntMaterial?.dispose();
    };
  }, [clippedIntMaterial]);

  const clippedStakloMaterial = useMemo(() => {
    const stakloNode = vStakloMesh ?? uStakloMesh;
    if (!stakloNode) return null;
    const base = Array.isArray(stakloNode.material)
      ? stakloNode.material[0]
      : stakloNode.material;
    const material = (base as THREE.MeshStandardMaterial).clone();
    material.clippingPlanes = clippingPlanes;
    material.clipShadows = true;
    material.needsUpdate = true;
    return material;
  }, [clippingPlanes, vStakloMesh, uStakloMesh]);

  useEffect(() => {
    return () => {
      clippedStakloMaterial?.dispose();
    };
  }, [clippedStakloMaterial]);

  return (
    <group position={position} scale={[mirrored ? -1 : 1, 1, 1]} dispose={null}>
      {/* Offset so the geometric center sits at origin */}
      <group
        position={[-centerOffset.x, -centerOffset.y, -centerOffset.z]}
        scale={[targetScaleX, targetScaleY, 1]}>
        {/* Front panel (-V) — scaled to match back panel dimensions, pivoting from its center */}
        <group
          position={[
            vScale.vCenter.x,
            vScale.vCenter.y,
            vScale.vCenter.z - 0.01,
          ]}>
          <group scale={[vScale.scaleX, vScale.scaleY, 1]}>
            <mesh
              castShadow
              receiveShadow
              geometry={nodes[vKey].geometry}
              material={clippedMaterial}
              position={[
                -vScale.vCenter.x,
                -vScale.vCenter.y,
                -vScale.vCenter.z,
              ]}
            />
            {vIntMesh && clippedIntMaterial && (
              <mesh
                receiveShadow
                geometry={vIntMesh.geometry}
                material={clippedIntMaterial}
                position={[
                  -vScale.vCenter.x,
                  -vScale.vCenter.y,
                  -vScale.vCenter.z,
                ]}
              />
            )}
            {vStakloMesh && clippedStakloMaterial && (
              <mesh
                castShadow
                geometry={vStakloMesh.geometry}
                material={clippedStakloMaterial}
                position={[
                  -vScale.vCenter.x,
                  -vScale.vCenter.y,
                  -vScale.vCenter.z,
                ]}
              />
            )}
          </group>
        </group>

        {/* Back panel (-U) — fits perfectly, no scaling needed */}
        <mesh
          castShadow
          receiveShadow
          geometry={nodes[uKey].geometry}
          material={clippedMaterial}
        />
        {uIntMesh && clippedIntMaterial && (
          <mesh
            receiveShadow
            geometry={uIntMesh.geometry}
            material={clippedIntMaterial}
          />
        )}
        {uStakloMesh && clippedStakloMaterial && (
          <mesh
            castShadow
            receiveShadow
            geometry={uStakloMesh.geometry}
            material={clippedStakloMaterial}
          />
        )}
      </group>
    </group>
  );
};

